<?php namespace App\Jobs; use App\Models\Order; use Barryvdh\DomPDF\Facade\Pdf; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Queue\Queueable; use Illuminate\Support\Facades\Storage; class GenerateInvoice implements ShouldQueue {use Queueable; public function __construct(public int $orderId){} public function handle():void {$order=Order::with('items','customer','vendor')->findOrFail($this->orderId);Storage::put("invoices/{$order->number}.pdf",Pdf::loadView('emails.orders.invoice',compact('order'))->output());} }
